-- Module 23: tenant-configurable loyalty rules backed by an immutable points ledger.
update public.module_definitions set configuration_schema='{"properties":{"points_label":{"type":"string","label":"Points label","maxLength":30,"default":"Points"},"automatic_sale_awards":{"type":"boolean","label":"Automatically award completed sales","default":true}},"additionalProperties":false}'::jsonb,updated_at=now()where key='loyalty';

insert into public.permissions(key,domain,action,description)values
 ('loyalty.read','loyalty','read','View loyalty balances, rules, and transaction history'),
 ('loyalty.manage','loyalty','manage','Configure loyalty rules and process point expiry'),
 ('loyalty.redeem','loyalty','redeem','Redeem customer loyalty points')
on conflict(key)do update set domain=excluded.domain,action=excluded.action,description=excluded.description;
create function private.install_loyalty_permissions(requested_organization_id uuid)returns void language plpgsql security definer set search_path='' as $$begin
 insert into public.role_permissions(role_id,permission_id)select role.id,permission.id from public.roles role cross join public.permissions permission where role.organization_id=requested_organization_id and role.key in('owner','administrator','manager')and permission.key like'loyalty.%'on conflict do nothing;
 insert into public.role_permissions(role_id,permission_id)select role.id,permission.id from public.roles role join public.permissions permission on permission.key=any(case role.key when'staff'then array['loyalty.read','loyalty.redeem']when'viewer'then array['loyalty.read']else array[]::text[]end)where role.organization_id=requested_organization_id and role.key in('staff','viewer')on conflict do nothing;
end;$$;
create function private.handle_main_branch_loyalty_permissions()returns trigger language plpgsql security definer set search_path='' as $$begin if new.code='main'then perform private.install_loyalty_permissions(new.organization_id);end if;return new;end;$$;
create trigger zzzzzzzz_install_loyalty_permissions_on_main_branch after insert on public.branches for each row execute function private.handle_main_branch_loyalty_permissions();select private.install_loyalty_permissions(id)from public.organizations;

create table public.loyalty_rules(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,name text not null check(char_length(btrim(name))between 1 and 120),rule_type text not null check(rule_type in('earn','redeem')),
 spend_amount numeric(16,4),points_amount integer not null check(points_amount>0),redemption_value numeric(16,4),priority integer not null default 100 check(priority between 0 and 1000),expiry_days integer,is_active boolean not null default true,
 created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),
 check((rule_type='earn'and spend_amount>0 and redemption_value is null and(expiry_days is null or expiry_days between 1 and 3650))or(rule_type='redeem'and spend_amount is null and redemption_value>0 and expiry_days is null))
);
create table public.customer_loyalty_balances(
 organization_id uuid not null references public.organizations(id)on delete cascade,customer_id uuid not null,points_balance integer not null default 0 check(points_balance>=0),lifetime_earned integer not null default 0 check(lifetime_earned>=0),lifetime_redeemed integer not null default 0 check(lifetime_redeemed>=0),lifetime_expired integer not null default 0 check(lifetime_expired>=0),updated_at timestamptz not null default now(),primary key(organization_id,customer_id),foreign key(customer_id,organization_id)references public.sales_customers(id,organization_id)on delete cascade
);
create table public.loyalty_transactions(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,customer_id uuid not null,transaction_type text not null check(transaction_type in('earn','redeem','expire','adjust')),points_delta integer not null check(points_delta<>0),balance_after integer not null check(balance_after>=0),rule_id uuid,sale_id uuid,monetary_value numeric(16,4)not null default 0 check(monetary_value>=0),idempotency_key text not null check(char_length(idempotency_key)between 1 and 200),description text check(char_length(description)<=500),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,idempotency_key),foreign key(customer_id,organization_id)references public.sales_customers(id,organization_id)on delete cascade,foreign key(rule_id,organization_id)references public.loyalty_rules(id,organization_id)on delete restrict,foreign key(sale_id,organization_id)references public.sales_transactions(id,organization_id)on delete restrict
);
create table public.loyalty_point_lots(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,customer_id uuid not null,earning_transaction_id uuid not null,original_points integer not null check(original_points>0),remaining_points integer not null check(remaining_points between 0 and original_points),expires_at timestamptz,created_at timestamptz not null default now(),unique(id,organization_id),unique(earning_transaction_id),foreign key(customer_id,organization_id)references public.sales_customers(id,organization_id)on delete cascade,foreign key(earning_transaction_id,organization_id)references public.loyalty_transactions(id,organization_id)on delete cascade
);
create table public.loyalty_redemption_allocations(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,redemption_transaction_id uuid not null,point_lot_id uuid not null,points_allocated integer not null check(points_allocated>0),created_at timestamptz not null default now(),unique(redemption_transaction_id,point_lot_id),foreign key(redemption_transaction_id,organization_id)references public.loyalty_transactions(id,organization_id)on delete cascade,foreign key(point_lot_id,organization_id)references public.loyalty_point_lots(id,organization_id)on delete restrict
);
create table public.loyalty_award_receipts(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,sale_id uuid not null,customer_id uuid not null,rule_id uuid,loyalty_transaction_id uuid,points_awarded integer not null check(points_awarded>=0),idempotency_key text not null check(char_length(idempotency_key)between 1 and 200),processed_at timestamptz not null default now(),unique(organization_id,sale_id),unique(organization_id,idempotency_key),foreign key(sale_id,organization_id)references public.sales_transactions(id,organization_id)on delete cascade,foreign key(customer_id,organization_id)references public.sales_customers(id,organization_id)on delete cascade,foreign key(rule_id,organization_id)references public.loyalty_rules(id,organization_id)on delete restrict,foreign key(loyalty_transaction_id,organization_id)references public.loyalty_transactions(id,organization_id)on delete restrict
);
create index loyalty_rules_active_idx on public.loyalty_rules(organization_id,rule_type,priority,id)where is_active;create index loyalty_balances_rank_idx on public.customer_loyalty_balances(organization_id,points_balance desc);create index loyalty_transactions_customer_idx on public.loyalty_transactions(customer_id,created_at desc);create index loyalty_transactions_sale_idx on public.loyalty_transactions(sale_id)where sale_id is not null;create index loyalty_lots_fifo_idx on public.loyalty_point_lots(customer_id,expires_at,created_at)where remaining_points>0;create index loyalty_lots_expiry_idx on public.loyalty_point_lots(organization_id,expires_at)where remaining_points>0 and expires_at is not null;create index loyalty_allocations_transaction_idx on public.loyalty_redemption_allocations(redemption_transaction_id);
create trigger set_updated_at before update on public.loyalty_rules for each row execute function private.set_updated_at();

create function private.loyalty_module_enabled(requested_organization_id uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='loyalty');$$;
create function private.loyalty_config(requested_organization_id uuid)returns jsonb language sql stable security definer set search_path='' as $$select coalesce(module.config,'{}')from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='loyalty';$$;
create function private.reject_loyalty_ledger_mutation()returns trigger language plpgsql set search_path='' as $$begin raise exception'Loyalty history is immutable.'using errcode='P0001';end;$$;
create trigger loyalty_transactions_immutable before update or delete on public.loyalty_transactions for each row execute function private.reject_loyalty_ledger_mutation();create trigger loyalty_allocations_immutable before update or delete on public.loyalty_redemption_allocations for each row execute function private.reject_loyalty_ledger_mutation();create trigger loyalty_awards_immutable before update or delete on public.loyalty_award_receipts for each row execute function private.reject_loyalty_ledger_mutation();

create function private.ensure_default_loyalty_rule()returns trigger language plpgsql security definer set search_path='' as $$declare definition_key text;actor uuid;begin select key into definition_key from public.module_definitions where id=new.module_id;if definition_key='loyalty'and new.is_enabled and not exists(select 1 from public.loyalty_rules where organization_id=new.organization_id and rule_type='earn')then select membership.user_id into actor from public.organization_memberships membership where membership.organization_id=new.organization_id and membership.status='active'order by membership.created_at limit 1;if actor is not null then insert into public.loyalty_rules(organization_id,name,rule_type,spend_amount,points_amount,priority,created_by,updated_by)values(new.organization_id,'Standard earning','earn',100,1,100,actor,actor);end if;end if;return new;end;$$;
create trigger ensure_default_loyalty_rule after insert or update of is_enabled on public.organization_modules for each row execute function private.ensure_default_loyalty_rule();
insert into public.loyalty_rules(organization_id,name,rule_type,spend_amount,points_amount,priority,created_by,updated_by)select module.organization_id,'Standard earning','earn',100,1,100,membership.user_id,membership.user_id from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id join lateral(select user_id from public.organization_memberships where organization_id=module.organization_id and status='active'order by created_at limit 1)membership on true where definition.key='loyalty'and module.is_enabled and not exists(select 1 from public.loyalty_rules where organization_id=module.organization_id and rule_type='earn');

create function private.save_loyalty_rule(requested_organization_id uuid,requested_rule_id uuid,requested_name text,requested_rule_type text,requested_spend_amount numeric,requested_points_amount integer,requested_redemption_value numeric,requested_priority integer,requested_expiry_days integer,requested_is_active boolean)returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());target_id uuid:=coalesce(requested_rule_id,gen_random_uuid());begin
 if actor is null or not private.loyalty_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'loyalty.manage',null)then raise exception'Permission denied.'using errcode='42501';end if;
 if char_length(btrim(requested_name))not between 1 and 120 or requested_rule_type not in('earn','redeem')or requested_points_amount<=0 or requested_priority not between 0 and 1000 or(requested_rule_type='earn'and(requested_spend_amount is null or requested_spend_amount<=0 or requested_redemption_value is not null or(requested_expiry_days is not null and requested_expiry_days not between 1 and 3650)))or(requested_rule_type='redeem'and(requested_spend_amount is not null or requested_redemption_value is null or requested_redemption_value<=0 or requested_expiry_days is not null))then raise exception'Invalid loyalty rule.'using errcode='22023';end if;
 if requested_rule_id is not null and not exists(select 1 from public.loyalty_rules where id=target_id and organization_id=requested_organization_id)then raise exception'Loyalty rule not found.'using errcode='22023';end if;
 insert into public.loyalty_rules(id,organization_id,name,rule_type,spend_amount,points_amount,redemption_value,priority,expiry_days,is_active,created_by,updated_by)values(target_id,requested_organization_id,btrim(requested_name),requested_rule_type,requested_spend_amount,requested_points_amount,requested_redemption_value,requested_priority,requested_expiry_days,requested_is_active,actor,actor)on conflict(id)do update set name=excluded.name,rule_type=excluded.rule_type,spend_amount=excluded.spend_amount,points_amount=excluded.points_amount,redemption_value=excluded.redemption_value,priority=excluded.priority,expiry_days=excluded.expiry_days,is_active=excluded.is_active,updated_by=actor;return target_id;
end;$$;

create function private.award_sale_loyalty(requested_organization_id uuid,requested_sale_id uuid,requested_idempotency_key text,requested_actor uuid)returns uuid language plpgsql security definer set search_path='' as $$
declare sale public.sales_transactions%rowtype;rule public.loyalty_rules%rowtype;points integer:=0;balance_value integer;transaction_id uuid;existing_transaction uuid;config jsonb;
begin
 if char_length(requested_idempotency_key)not between 1 and 200 then raise exception'Invalid idempotency key.'using errcode='22023';end if;
 select*into sale from public.sales_transactions where id=requested_sale_id and organization_id=requested_organization_id;if sale.id is null or sale.status<>'completed'or sale.customer_id is null or requested_actor is null then raise exception'Completed customer sale not found.'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(requested_organization_id::text||':'||sale.customer_id::text,0));select loyalty_transaction_id into existing_transaction from public.loyalty_award_receipts where organization_id=requested_organization_id and idempotency_key=requested_idempotency_key;if found then return existing_transaction;end if;
 config:=private.loyalty_config(requested_organization_id);if not private.loyalty_module_enabled(requested_organization_id)or not coalesce((config->>'automatic_sale_awards')::boolean,true)then return null;end if;
 select*into rule from public.loyalty_rules where organization_id=requested_organization_id and rule_type='earn'and is_active order by priority,id limit 1;if rule.id is not null then points:=floor(sale.total/rule.spend_amount)::integer*rule.points_amount;end if;
 if points>0 then insert into public.customer_loyalty_balances(organization_id,customer_id,points_balance,lifetime_earned)values(requested_organization_id,sale.customer_id,points,points)on conflict(organization_id,customer_id)do update set points_balance=public.customer_loyalty_balances.points_balance+excluded.points_balance,lifetime_earned=public.customer_loyalty_balances.lifetime_earned+excluded.lifetime_earned,updated_at=now()returning points_balance into balance_value;insert into public.loyalty_transactions(organization_id,customer_id,transaction_type,points_delta,balance_after,rule_id,sale_id,idempotency_key,description,created_by)values(requested_organization_id,sale.customer_id,'earn',points,balance_value,rule.id,sale.id,requested_idempotency_key,'Points earned from '||sale.receipt_number,requested_actor)returning id into transaction_id;insert into public.loyalty_point_lots(organization_id,customer_id,earning_transaction_id,original_points,remaining_points,expires_at)values(requested_organization_id,sale.customer_id,transaction_id,points,points,case when rule.expiry_days is null then null else now()+make_interval(days=>rule.expiry_days)end);insert into public.customer_loyalty_activity(organization_id,customer_id,activity_type,points_delta,description,reference_type,reference_id,created_by)values(requested_organization_id,sale.customer_id,'earn',points,'Points earned from '||sale.receipt_number,'loyalty_transaction',transaction_id,requested_actor);end if;
 insert into public.loyalty_award_receipts(organization_id,sale_id,customer_id,rule_id,loyalty_transaction_id,points_awarded,idempotency_key)values(requested_organization_id,sale.id,sale.customer_id,rule.id,transaction_id,points,requested_idempotency_key);return transaction_id;
exception when unique_violation then select loyalty_transaction_id into existing_transaction from public.loyalty_award_receipts where organization_id=requested_organization_id and(idempotency_key=requested_idempotency_key or sale_id=requested_sale_id);return existing_transaction;end;$$;

create function private.expire_customer_loyalty_points(requested_organization_id uuid,requested_customer_id uuid,requested_as_of timestamptz,requested_actor uuid)returns integer language plpgsql security definer set search_path='' as $$declare lot public.loyalty_point_lots%rowtype;balance_value integer;transaction_id uuid;expired_total integer:=0;begin
 perform pg_advisory_xact_lock(hashtextextended(requested_organization_id::text||':'||requested_customer_id::text,0));for lot in select*from public.loyalty_point_lots where organization_id=requested_organization_id and customer_id=requested_customer_id and remaining_points>0 and expires_at is not null and expires_at<=requested_as_of order by expires_at,created_at,id for update loop update public.customer_loyalty_balances set points_balance=points_balance-lot.remaining_points,lifetime_expired=lifetime_expired+lot.remaining_points,updated_at=now()where organization_id=requested_organization_id and customer_id=requested_customer_id returning points_balance into balance_value;insert into public.loyalty_transactions(organization_id,customer_id,transaction_type,points_delta,balance_after,idempotency_key,description,created_by)values(requested_organization_id,requested_customer_id,'expire',-lot.remaining_points,balance_value,'expiry:'||lot.id,'Expired loyalty points',requested_actor)returning id into transaction_id;insert into public.customer_loyalty_activity(organization_id,customer_id,activity_type,points_delta,description,reference_type,reference_id,created_by)values(requested_organization_id,requested_customer_id,'expire',-lot.remaining_points,'Expired loyalty points','loyalty_transaction',transaction_id,requested_actor);expired_total:=expired_total+lot.remaining_points;update public.loyalty_point_lots set remaining_points=0 where id=lot.id;end loop;return expired_total;end;$$;

create function private.redeem_loyalty_points(requested_organization_id uuid,requested_customer_id uuid,requested_rule_id uuid,requested_points integer,requested_idempotency_key text,requested_description text)returns uuid language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid());rule public.loyalty_rules%rowtype;lot public.loyalty_point_lots%rowtype;remaining integer;allocated integer;balance_value integer;transaction_id uuid;existing_id uuid;monetary numeric;
begin
 if actor is null or not private.loyalty_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'loyalty.redeem',null)then raise exception'Permission denied.'using errcode='42501';end if;if requested_points<=0 or char_length(requested_idempotency_key)not between 1 and 200 or char_length(coalesce(requested_description,''))>500 then raise exception'Invalid redemption.'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(requested_organization_id::text||':'||requested_customer_id::text,0));select id into existing_id from public.loyalty_transactions where organization_id=requested_organization_id and idempotency_key=requested_idempotency_key;if found then return existing_id;end if;perform private.expire_customer_loyalty_points(requested_organization_id,requested_customer_id,now(),actor);
 select*into rule from public.loyalty_rules where id=requested_rule_id and organization_id=requested_organization_id and rule_type='redeem'and is_active;if rule.id is null or requested_points%rule.points_amount<>0 then raise exception'Points do not match the redemption rule.'using errcode='22023';end if;select points_balance into balance_value from public.customer_loyalty_balances where organization_id=requested_organization_id and customer_id=requested_customer_id for update;if coalesce(balance_value,0)<requested_points then raise exception'Insufficient loyalty points.'using errcode='P0001';end if;
 monetary:=requested_points/rule.points_amount*rule.redemption_value;balance_value:=balance_value-requested_points;update public.customer_loyalty_balances set points_balance=balance_value,lifetime_redeemed=lifetime_redeemed+requested_points,updated_at=now()where organization_id=requested_organization_id and customer_id=requested_customer_id;insert into public.loyalty_transactions(organization_id,customer_id,transaction_type,points_delta,balance_after,rule_id,monetary_value,idempotency_key,description,created_by)values(requested_organization_id,requested_customer_id,'redeem',-requested_points,balance_value,rule.id,monetary,requested_idempotency_key,coalesce(nullif(btrim(requested_description),''),rule.name),actor)returning id into transaction_id;
 remaining:=requested_points;for lot in select*from public.loyalty_point_lots where organization_id=requested_organization_id and customer_id=requested_customer_id and remaining_points>0 and(expires_at is null or expires_at>now())order by expires_at nulls last,created_at,id for update loop exit when remaining=0;allocated:=least(remaining,lot.remaining_points);update public.loyalty_point_lots set remaining_points=remaining_points-allocated where id=lot.id;insert into public.loyalty_redemption_allocations(organization_id,redemption_transaction_id,point_lot_id,points_allocated)values(requested_organization_id,transaction_id,lot.id,allocated);remaining:=remaining-allocated;end loop;if remaining<>0 then raise exception'Point lots are inconsistent with the customer balance.'using errcode='P0001';end if;insert into public.customer_loyalty_activity(organization_id,customer_id,activity_type,points_delta,description,reference_type,reference_id,created_by)values(requested_organization_id,requested_customer_id,'redeem',-requested_points,coalesce(nullif(btrim(requested_description),''),rule.name),'loyalty_transaction',transaction_id,actor);return transaction_id;
exception when unique_violation then select id into existing_id from public.loyalty_transactions where organization_id=requested_organization_id and idempotency_key=requested_idempotency_key;return existing_id;end;$$;

create function private.process_loyalty_expiries(requested_organization_id uuid,requested_as_of timestamptz)returns integer language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());customer_value uuid;expired_total integer:=0;begin if actor is null or not private.loyalty_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'loyalty.manage',null)then raise exception'Permission denied.'using errcode='42501';end if;for customer_value in select distinct customer_id from public.loyalty_point_lots where organization_id=requested_organization_id and remaining_points>0 and expires_at is not null and expires_at<=requested_as_of order by customer_id loop expired_total:=expired_total+private.expire_customer_loyalty_points(requested_organization_id,customer_value,requested_as_of,actor);end loop;return expired_total;end;$$;
create function private.handle_completed_sale_loyalty()returns trigger language plpgsql security definer set search_path='' as $$begin if new.status='completed'and new.customer_id is not null and new.total>0 then perform private.award_sale_loyalty(new.organization_id,new.id,'sale:'||new.id,new.created_by);end if;return new;end;$$;
create trigger award_completed_sale_loyalty after insert or update of status,total on public.sales_transactions for each row execute function private.handle_completed_sale_loyalty();

create function public.save_loyalty_rule(requested_organization_id uuid,requested_rule_id uuid,requested_name text,requested_rule_type text,requested_spend_amount numeric,requested_points_amount integer,requested_redemption_value numeric,requested_priority integer,requested_expiry_days integer,requested_is_active boolean)returns uuid language sql security definer set search_path='' as $$select private.save_loyalty_rule(requested_organization_id,requested_rule_id,requested_name,requested_rule_type,requested_spend_amount,requested_points_amount,requested_redemption_value,requested_priority,requested_expiry_days,requested_is_active);$$;
create function public.award_sale_loyalty(requested_organization_id uuid,requested_sale_id uuid,requested_idempotency_key text)returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());branch uuid;begin select branch_id into branch from public.sales_transactions where id=requested_sale_id and organization_id=requested_organization_id;if actor is null or branch is null or not private.can_business_permission(requested_organization_id,'loyalty.manage',branch)then raise exception'Permission denied.'using errcode='42501';end if;return private.award_sale_loyalty(requested_organization_id,requested_sale_id,requested_idempotency_key,actor);end;$$;
create function public.redeem_loyalty_points(requested_organization_id uuid,requested_customer_id uuid,requested_rule_id uuid,requested_points integer,requested_idempotency_key text,requested_description text)returns uuid language sql security definer set search_path='' as $$select private.redeem_loyalty_points(requested_organization_id,requested_customer_id,requested_rule_id,requested_points,requested_idempotency_key,requested_description);$$;
create function public.process_loyalty_expiries(requested_organization_id uuid,requested_as_of timestamptz)returns integer language sql security definer set search_path='' as $$select private.process_loyalty_expiries(requested_organization_id,requested_as_of);$$;
create or replace function public.record_customer_loyalty(requested_organization_id uuid,requested_customer_id uuid,requested_type text,requested_points integer,requested_description text,requested_reference_type text,requested_reference_id uuid)returns uuid language plpgsql security definer set search_path='' as $$begin if private.loyalty_module_enabled(requested_organization_id)then raise exception'Use the Loyalty module for point changes.'using errcode='P0001';end if;return private.record_customer_loyalty(requested_organization_id,requested_customer_id,requested_type,requested_points,requested_description,requested_reference_type,requested_reference_id);end;$$;

alter table public.loyalty_rules enable row level security;alter table public.customer_loyalty_balances enable row level security;alter table public.loyalty_transactions enable row level security;alter table public.loyalty_point_lots enable row level security;alter table public.loyalty_redemption_allocations enable row level security;alter table public.loyalty_award_receipts enable row level security;
create policy loyalty_rules_read on public.loyalty_rules for select to authenticated using((select private.loyalty_module_enabled(organization_id))and private.can_business_permission(organization_id,'loyalty.read',null));create policy loyalty_balances_read on public.customer_loyalty_balances for select to authenticated using((select private.loyalty_module_enabled(organization_id))and private.can_business_permission(organization_id,'loyalty.read',null));create policy loyalty_transactions_read on public.loyalty_transactions for select to authenticated using((select private.loyalty_module_enabled(organization_id))and private.can_business_permission(organization_id,'loyalty.read',null));create policy loyalty_lots_read on public.loyalty_point_lots for select to authenticated using((select private.loyalty_module_enabled(organization_id))and private.can_business_permission(organization_id,'loyalty.read',null));create policy loyalty_allocations_read on public.loyalty_redemption_allocations for select to authenticated using((select private.loyalty_module_enabled(organization_id))and private.can_business_permission(organization_id,'loyalty.read',null));create policy loyalty_awards_read on public.loyalty_award_receipts for select to authenticated using((select private.loyalty_module_enabled(organization_id))and private.can_business_permission(organization_id,'loyalty.read',null));
revoke all on table public.loyalty_rules,public.customer_loyalty_balances,public.loyalty_transactions,public.loyalty_point_lots,public.loyalty_redemption_allocations,public.loyalty_award_receipts from public,anon,authenticated;grant select on table public.loyalty_rules,public.customer_loyalty_balances,public.loyalty_transactions,public.loyalty_point_lots,public.loyalty_redemption_allocations,public.loyalty_award_receipts to authenticated;
revoke all on function private.install_loyalty_permissions(uuid),private.handle_main_branch_loyalty_permissions(),private.loyalty_module_enabled(uuid),private.loyalty_config(uuid),private.reject_loyalty_ledger_mutation(),private.ensure_default_loyalty_rule(),private.save_loyalty_rule(uuid,uuid,text,text,numeric,integer,numeric,integer,integer,boolean),private.award_sale_loyalty(uuid,uuid,text,uuid),private.expire_customer_loyalty_points(uuid,uuid,timestamptz,uuid),private.redeem_loyalty_points(uuid,uuid,uuid,integer,text,text),private.process_loyalty_expiries(uuid,timestamptz),private.handle_completed_sale_loyalty()from public,anon,authenticated;grant execute on function private.loyalty_module_enabled(uuid)to authenticated;
revoke all on function public.save_loyalty_rule(uuid,uuid,text,text,numeric,integer,numeric,integer,integer,boolean),public.award_sale_loyalty(uuid,uuid,text),public.redeem_loyalty_points(uuid,uuid,uuid,integer,text,text),public.process_loyalty_expiries(uuid,timestamptz)from public,anon;grant execute on function public.save_loyalty_rule(uuid,uuid,text,text,numeric,integer,numeric,integer,integer,boolean),public.award_sale_loyalty(uuid,uuid,text),public.redeem_loyalty_points(uuid,uuid,uuid,integer,text,text),public.process_loyalty_expiries(uuid,timestamptz)to authenticated;
comment on table public.loyalty_transactions is'Immutable loyalty points ledger. Balances are safely materialized under a per-customer advisory transaction lock.';comment on table public.loyalty_point_lots is'FIFO earning lots preserve point provenance and support configurable future expiry processing.';comment on function public.award_sale_loyalty(uuid,uuid,text)is'Idempotent replay boundary for completed sale loyalty awards.';
